(()=>{const feature=document.querySelector("[data-experience]");if(!feature||window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;const number=feature.querySelector("[data-experience-count]");let started=false;const play=()=>{if(started)return;started=true;feature.classList.add("is-revealing");const start=performance.now();const frame=now=>{const progress=Math.min(1,(now-start)/1900);number.textContent=String(Math.round(30*(1-Math.pow(1-progress,3))));if(progress<1)requestAnimationFrame(frame)};requestAnimationFrame(frame)};if("IntersectionObserver"in window){const observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){observer.disconnect();play()}},{threshold:.4});observer.observe(feature)}else play()})();